import React from "react";
import {
  DatePicker as ArcoDatePicker,
  DatePickerProps as ArcoDatePickerProps,
  WeekPickerProps as ArcoWeekPickerProps,
  MonthPickerProps as ArcoMonthPickerProps,
  YearPickerProps as AcroYearPickerProps,
  QuarterPickerProps as AcroQuarterPickerProps,
  RangePickerProps as ArcoRangePickerProps,
  RangePickerProps,
} from "@arco-design/web-react";
import { connect, mapProps, mapReadPretty } from "@formily/react";
import dayjs, { Dayjs } from "dayjs";
import { PreviewText } from "../PreviewText";
import quarterOfYear from "dayjs/plugin/quarterOfYear";
import isoWeek from "dayjs/plugin/isoWeek";
dayjs.extend(quarterOfYear);
/**
 * arco 用的应该是iso week...by 林昊
 */
dayjs.extend(isoWeek);

type ComposedDatePicker = React.FC<ArcoDatePickerProps> & {
  WeekPicker?: React.FC<ArcoWeekPickerProps>;
  MonthPicker?: React.FC<ArcoMonthPickerProps>;
  YearPicker?: React.FC<AcroYearPickerProps>;
  QuarterPicker?: React.FC<AcroQuarterPickerProps>;
  RangePicker?: React.FC<ArcoRangePickerProps>;
};

type PickerType =
  | "DatePicker"
  | "WeekPicker"
  | "MonthPicker"
  | "YearPicker"
  | "QuarterPicker"
  | "RangePicker";
type RangeMode = RangePickerProps["mode"];

const getDefaultFormat = (showTime: boolean, type: PickerType) => {
  switch (type) {
    case "DatePicker":
      return showTime ? "YYYY-MM-DD HH:mm:ss" : "YYYY-MM-DD";
    case "WeekPicker":
      return "gggg-wo";
    case "MonthPicker":
      return "YYYY-MM";
    case "YearPicker":
      return "YYYY";
    case "QuarterPicker":
      return "YYYY-[Q]Q";
    default:
      return showTime ? "YYYY-MM-DD HH:mm:ss" : "YYYY-MM-DD";
  }
};

const getRangeDefaultFormat = (showTime: boolean, rangeMode: RangeMode) => {
  switch (rangeMode) {
    case "date":
      return getDefaultFormat(showTime, "DatePicker");
    case "month":
      return getDefaultFormat(showTime, "MonthPicker");
    case "quarter":
      return getDefaultFormat(showTime, "QuarterPicker");
    case "week":
      return getDefaultFormat(showTime, "WeekPicker");
    case "year":
      return getDefaultFormat(showTime, "YearPicker");

    default:
      return getDefaultFormat(showTime, "DatePicker");
  }
};

const numericPatterns = {
  week: `(?<week>5[0-3]|[0-4]?[0-9]).*`,
  year: `(?<year>[1-9][0-9]{3})`,
  quarter: `(?<quarter>[1-4])`,
};

const parseQuarterString = (value = "", format: string) => {
  const quarterRegex = /\[([^\]]+)]|YYYY|Q/g;
  const testRegex = new RegExp(
    format.replace(quarterRegex, (match) => {
      switch (match) {
        case "Q":
          return numericPatterns.quarter;
        case "YYYY":
          return numericPatterns.year;
        default:
          return match;
      }
    })
  );

  const result = value.match(testRegex)?.groups;
  return result
    ? dayjs()
        .year(+result.year)
        .quarter(+result.quarter)
    : undefined;
};

const parseWeekString = (value = "", format: string) => {
  const weekRegex = /\[([^\]]+)]|wo|gggg/g;
  const yearWeekRegex = new RegExp(
    format.replace(weekRegex, (match) => {
      switch (match) {
        case "gggg":
          return numericPatterns.year;
        case "wo":
          return numericPatterns.week;
        default:
          return match;
      }
    })
  );

  const groupResult = value.match(yearWeekRegex)?.groups;

  const res = groupResult
    ? dayjs()
        .year(+groupResult.year)
        .isoWeek(+groupResult.week)
    : undefined;
  return res;
};

const parserMap = {
  WeekPicker: parseWeekString,
  QuarterPicker: parseQuarterString,
  RangePicker: {
    quarter: parseQuarterString,
    week: parseWeekString,
  },
};

/**
 * 因为dayjs不支持解析周和季度,临时做一个解析
 */
const transformDateString = (props: {
  value?: string | string[];
  type: PickerType;
  format: string;
  rangeMode?: RangeMode;
}) => {
  const { value, type, format, rangeMode } = props;
  if (value == null) return value;
  if (type === "WeekPicker" || type === "QuarterPicker") {
    const parser = parserMap[type];
    if (!parser) return value;
    if (Array.isArray(value)) {
      return value.map((k) => parser(k, format));
    } else {
      return parser(value, format);
    }
  }
  if (type === "RangePicker" && rangeMode) {
    const parser = parserMap[type][rangeMode];
    if (!parser) return value;
    if (Array.isArray(value)) {
      return value.map((k) => parser(k, format));
    }
  }
  return value;
};

const mapDateFormat = (type: PickerType) => (props: any, field: any) => {
  const { onChange, mode, showTime } = props;

  const format =
    props?.format ??
    (mode
      ? getRangeDefaultFormat(showTime, mode)
      : getDefaultFormat(showTime, type));

  const value = field?.value || props?.value;
  return {
    ...props,
    format,
    value: transformDateString({
      value,
      format,
      type,
      rangeMode: mode,
    }),
    onChange: (dateString: string | string[], date: Dayjs | Dayjs[]) => {
      if (onChange) {
        onChange(dateString);
      }
    },
  };
};

const DatePicker: ComposedDatePicker = connect(
  ArcoDatePicker,
  mapProps(mapDateFormat("DatePicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getDefaultFormat(props?.showTime, "DatePicker");
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);

const WeekPicker = connect(
  ArcoDatePicker.WeekPicker,
  mapProps(mapDateFormat("WeekPicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getDefaultFormat(props?.showTime, "WeekPicker");
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);
DatePicker.WeekPicker = WeekPicker;

const MonthPicker = connect(
  ArcoDatePicker.MonthPicker,
  mapProps(mapDateFormat("MonthPicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getDefaultFormat(props?.showTime, "MonthPicker");
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);
DatePicker.MonthPicker = MonthPicker;

const YearPicker = connect(
  ArcoDatePicker.YearPicker,
  mapProps(mapDateFormat("YearPicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getDefaultFormat(props?.showTime, "YearPicker");
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);
DatePicker.YearPicker = YearPicker;

const QuarterPicker = connect(
  ArcoDatePicker.QuarterPicker,
  mapProps(mapDateFormat("QuarterPicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getDefaultFormat(props?.showTime, "QuarterPicker");
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);
DatePicker.QuarterPicker = QuarterPicker;

const RangePicker = connect(
  ArcoDatePicker.RangePicker,
  mapProps(mapDateFormat("RangePicker")),
  mapReadPretty((props) => {
    const format =
      props.format ?? getRangeDefaultFormat(props?.showTime, props?.mode);
    return <PreviewText.DatePicker {...props} format={format} />;
  })
);
DatePicker.RangePicker = RangePicker;

export default DatePicker;
